() => {
  // turn demo OFF to prove this is not demo-specific
  document.querySelector('#dtoggle').click();
  const q = document.querySelector('#q');
  const test = (term) => {
    q.value = term;
    q.dispatchEvent(new Event('input', {bubbles:true}));
    const trs = [...document.querySelectorAll('#tbody tr')];
    const isEmpty = trs.length===1 && trs[0].querySelector('.empty');
    return { term, rows: isEmpty ? 0 : trs.length, foot: document.querySelector('#footInfo').textContent.trim() };
  };
  const results = ['卡仓','断货','待发','临期','Temu','虚拟仓'].map(test);
  // reset
  q.value=''; q.dispatchEvent(new Event('input',{bubbles:true}));
  document.querySelector('#stateChips .chip[data-s="all"]').click();
  return results;
}

