      发货渠道: stuck['发货渠道'], 品名: stuck['品名'], 店铺: stuck['店铺']
    } : null,
    // does any searchable field contain '卡仓'?
    searchFieldsHaveKacang: stuck ? ['包裹号','订单号','SKU','MSKU','店铺','品名','产品标题','仓库','发货渠道']
      .some(f => String(stuck[f]||'').includes('卡仓')) : null
  };
}');
