input.new_string:
$('#q').oninput=(e)=>{
  let text=e.target.value.trim().toLowerCase();
  for(const key in KW){
    const kl=key.toLowerCase();
    if(text.includes(kl)){
      const[type,val]=KW[key];
      if(type==='state'){stateFilter=val;document.querySelectorAll('#stateChips .chip').forEach(x=>x.classList.toggle('on',x.dataset.s===val));}
      if(type==='anom'){activeAnom=val;renderAnom();}
      text=text.split(kl).join(' ');   // 关键词已转成语义筛选，从文本子串检索里剔除，避免把命中单误杀
    }
  }
  q=text.trim();   // 仅剩余文本做子串检索；纯关键词（如「卡仓」）→ q='' → 只走异常筛选
  apply();
};

