input.function:
() => {
  const q = document.querySelector('#q');
  const reset = () => {
    const aa = document.querySelector('.arow.active'); if(aa) aa.click();
    const zz = document.querySelector('.zbtn.active'); if(zz) zz.click();
    document.querySelector('#stateChips .chip[data-s="all"]').click();
    q.value=''; q.dispatchEvent(new Event('input',{bubbles:true}));
  };
  const test = (term) => {
    reset();
    q.value = term; q.dispatchEvent(new Event('input',{bubbles:true}));
    const trs = [...document.querySelectorAll('#tbody tr')];
    const isEmpty = trs.length===1 && trs[0].querySelector('.empty');
    const n = isEmpty ? 0 : trs.length;
    const firstPkg = isEmpty ? null : (trs[0].querySelector('a.pkglink')?.textContent || null);
    return { term, rows: n, firstPkg };
  };
  const results = ['卡仓','虚拟仓','临期','待发','已发','Temu','Amazon','断货'].map(test);
  reset();
  return results;
}

